<?php
declare(strict_types=1);
require __DIR__ . '/../app/bootstrap.php';
$u=require_login();require_role('supply','approver','admin');$report=(string)($_GET['report']??'stock');
if(!in_array($report,['stock','low','movements','usage','assets','integrity','executive'],true)){http_response_code(400);exit('รายงานไม่ถูกต้อง');}if($report==='integrity')require_role('supply','admin');
$safe=function(mixed$v):string{$v=(string)$v;if(preg_match('/^[=+\-@\t\r]/u',$v))$v="'".$v;return$v;};
header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$report.'-'.date('Ymd-His').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');
if($report==='executive'){$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from']??''))?$_GET['from']:date('Y-m-01',strtotime('-11 months'));$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to']??''))?$_GET['to']:date('Y-m-d');$data=(new ExecutiveReportService(db()))->build($from,$to);fputcsv($out,['หมวดข้อมูล','รายการ','หน่วย','ค่าหลัก','ค่าเปรียบเทียบ','จำนวนคำขอ/รายละเอียด'],',','"','');foreach($data['materials']as$row)fputcsv($out,array_map($safe,['วัสดุใช้มาก',$row['code'].' · '.$row['name'],$row['unit'],$row['issued_qty'],'',$row['request_count'].' คำขอ']),',','"','');foreach($data['groups']as$row)fputcsv($out,array_map($safe,['กลุ่มงาน',$row['group_name'],'',$row['request_count'].' คำขอ',$row['issue_count'].' ใบจ่าย',$row['material_count'].' วัสดุ']),',','"','');foreach($data['anomalies']as$row)fputcsv($out,array_map($safe,['ใช้เพิ่มผิดปกติ',$row['code'].' · '.$row['name'],$row['unit'],$row['current_qty'],$row['previous_qty'],'30 วันล่าสุดเทียบ 30 วันก่อน']),',','"','');foreach($data['forecast']as$row)fputcsv($out,array_map($safe,['ประมาณการคงเหลือ',$row['code'].' · '.$row['name'],$row['unit'],$row['stock_qty'],$row['minimum_qty'],$row['days_left']===null?'ข้อมูลไม่พอ':$row['days_left'].' วัน']),',','"','');fclose($out);exit;}
if($report==='stock'||$report==='low'){$headers=['รหัส','ชื่อวัสดุ','หมวดหมู่','หน่วย','คงเหลือ','ยอดขั้นต่ำ','ตำแหน่ง','สถานะ'];$sql='SELECT m.code,m.name,COALESCE(c.name,\'\'),m.unit,m.stock_qty,m.minimum_qty,m.location,IF(m.active,\'เปิดใช้งาน\',\'ปิดใช้งาน\') FROM materials m LEFT JOIN categories c ON c.id=m.category_id'.($report==='low'?' WHERE m.active=1 AND m.stock_qty<=m.minimum_qty':'').' ORDER BY m.name';}
elseif($report==='movements'){$headers=['ID','วันเวลา','รหัส','ชื่อวัสดุ','ประเภท','เปลี่ยนแปลง','คงเหลือหลังรายการ','เอกสารอ้างอิง','เหตุผล','ผู้บันทึก'];$sql='SELECT sm.id,sm.created_at,m.code,m.name,sm.movement_type,sm.quantity_delta,sm.balance_after,sm.reference_no,sm.reason,u.full_name FROM stock_movements sm JOIN materials m ON m.id=sm.material_id JOIN users u ON u.id=sm.created_by ORDER BY sm.id DESC';}
elseif($report==='usage'){$headers=['เลขคำขอ','วันที่ส่ง','ผู้เบิก','กลุ่มงาน','วัสดุ','หน่วย','จำนวนขอ','จำนวนอนุมัติ','จำนวนจ่าย'];$sql='SELECT r.request_no,r.submitted_at,u.full_name,COALESCE(g.name,\'\'),m.name,m.unit,ri.requested_qty,ri.approved_qty,ri.issued_qty FROM requisition_items ri JOIN requisitions r ON r.id=ri.requisition_id JOIN users u ON u.id=r.requester_id LEFT JOIN work_groups g ON g.id=r.work_group_id JOIN materials m ON m.id=ri.material_id ORDER BY r.id DESC';}
elseif($report==='integrity'){$headers=['รหัส','วัสดุ','หน่วย','ยอดปัจจุบัน','ยอดรวม Ledger','ยอด Movement ล่าสุด','ผลต่าง','จำนวน Movement','สถานะ'];$sql="SELECT m.code,m.name,m.unit,m.stock_qty,COALESCE(SUM(sm.quantity_delta),0),(SELECT sm2.balance_after FROM stock_movements sm2 WHERE sm2.material_id=m.id ORDER BY sm2.id DESC LIMIT 1),(m.stock_qty-COALESCE(SUM(sm.quantity_delta),0)),COUNT(sm.id),IF(ABS(m.stock_qty-COALESCE(SUM(sm.quantity_delta),0))<0.0005 AND ABS(m.stock_qty-COALESCE((SELECT sm3.balance_after FROM stock_movements sm3 WHERE sm3.material_id=m.id ORDER BY sm3.id DESC LIMIT 1),0))<0.0005,'ถูกต้อง','ต้องตรวจสอบ') FROM materials m LEFT JOIN stock_movements sm ON sm.material_id=m.id GROUP BY m.id,m.code,m.name,m.unit,m.stock_qty ORDER BY m.name";}
else{$headers=['ผู้รับ','วัสดุ','หน่วย','จำนวนรับ','คืนแล้ว','คงค้าง','เลขคำขอ','วันที่รับ'];$sql='SELECT u.full_name,m.name,m.unit,aa.quantity,aa.returned_qty,(aa.quantity-aa.returned_qty),r.request_no,aa.assigned_at FROM asset_assignments aa JOIN users u ON u.id=aa.assigned_user_id JOIN materials m ON m.id=aa.material_id JOIN requisition_items ri ON ri.id=aa.requisition_item_id JOIN requisitions r ON r.id=ri.requisition_id WHERE aa.quantity>aa.returned_qty ORDER BY aa.assigned_at DESC';}
$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from']??''))?$_GET['from']:'';$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to']??''))?$_GET['to']:'';
$lookup=function(string$table,string$column,int$id):string{if($id<=0)return'';$allowed=['materials'=>'name','users'=>'full_name','work_groups'=>'name'];if(!isset($allowed[$table])||$allowed[$table]!==$column)return'';$s=db()->prepare("SELECT `$column` FROM `$table` WHERE id=?");$s->execute([$id]);return(string)($s->fetchColumn()?:'');};
$materialName=$lookup('materials','name',(int)($_GET['material_id']??0));$requesterName=$lookup('users','full_name',(int)($_GET['requester_id']??0));$groupName=$lookup('work_groups','name',(int)($_GET['group_id']??0));
fputcsv($out,$headers,',','"','');$s=db()->query($sql);while($row=$s->fetch(PDO::FETCH_NUM)){$date=$report==='movements'?substr((string)$row[1],0,10):($report==='usage'?substr((string)$row[1],0,10):'');if($date&&(($from&&$date<$from)||($to&&$date>$to)))continue;if($report==='movements'&&$materialName!==''&&(string)$row[3]!==$materialName)continue;if($report==='usage'&&(($materialName!==''&&(string)$row[4]!==$materialName)||($requesterName!==''&&(string)$row[2]!==$requesterName)||($groupName!==''&&(string)$row[3]!==$groupName)))continue;fputcsv($out,array_map($safe,$row),',','"','');}fclose($out);exit;
